1	// The one SessionEnd command a consumer's .claude/settings.json wires. Like its
2	// siblings the address is the stable contract (#385: the settings file changes as
3	// seldom as possible), and like the SessionStart orchestrator it is a RUNNER, not a
4	// step: it invokes each ACTIVE pack's own `session-end.mjs`, discovered structurally
5	// exactly as tasks, prose and skills are. Core never names the pack whose step it
6	// runs, and never learns what one does — a session-end step is pack content, and the
7	// engine's whole part is "invoke it, once, when the session ends"
8	// (skill-usage-metrics DESIGN §3.3).
9	//
10	// SessionEnd, not Stop. Stop fires at every turn end (and already runs the
11	// conformance checks); a step that writes anything per-session would fire once per
12	// TURN there. SessionEnd fires once, when the session ends.
13	//
14	// BEST EFFORT AS A HOOK, and that is enough there: a container reclaimed by timeout
15	// never fires it, so nothing may depend on it having run — every firing strictly
16	// enriches the record, every miss leaves exactly the prior behaviour.
17	//
18	// AND EXPLICITLY INVOCABLE, which is what makes unattended sessions countable at
19	// all. An UNATTENDED session — the scheduler's executor, running a dispatch in a
20	// cloud container nobody is sitting in front of — ends when its container is
21	// reclaimed, so the hook is exactly the firing that does not happen, and every one
22	// of those sessions used to leave no record anywhere. So the executor runs this
23	// runner itself as its last step (engine/scheduler/executor.md), naming the dispatch
24	// issue in `CLAUDINITE_SESSION_ISSUE`. Steps must therefore tolerate being run
25	// mid-session: the transcript is complete only up to the invocation, and the later
26	// hook firing (when it happens at all) is a second event over the same session,
27	// which the capture step's session-keyed delta already makes safe.
28	//
29	// FAIL-SOFT, absolutely. A session must never fail to end because of this hook, so
30	// every error — a step that throws, a step that hangs, a broken pack registry — is
31	// swallowed, recorded via hooklog, and exited 0. The per-step bound is a hard kill;
32	// nothing here can wedge a session.
33	import { spawnSync } from 'node:child_process';
34	import { existsSync, readFileSync } from 'node:fs';
35	import { join, dirname } from 'node:path';
36	import { fileURLToPath } from 'node:url';
37	import { hooklog } from '../checks/helpers/hook-log.mjs';
38	
39	// The step file an active pack contributes, if it ships one.
40	export const STEP_FILE = 'session-end.mjs';
41	
42	// A step gets this long before it is killed. Generous — a capture step pushes to a
43	// remote — but finite: a hung step must not hold the session open.
44	const STEP_TIMEOUT_MS = 120_000;
45	
46	const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
47	const engineRoot = dirname(dirname(fileURLToPath(import.meta.url)));
48	
49	// Claude Code passes the hook's input JSON on stdin: { session_id, transcript_path,
50	// reason, … }. A manual run (TTY, or nothing parseable) simply hands the steps
51	// nothing and they fall back to their own discovery.
52	function hookInput() {
53	  try {
54	    if (process.stdin.isTTY) return {};
55	    const raw = readFileSync(0, 'utf8');
56	    return raw.trim() ? JSON.parse(raw) : {};
57	  } catch { return {}; }
58	}
59	
60	async function main() {
61	  const input = hookInput();
62	  const configPath = join(projectRoot, '.claudinite-checks.json');
63	  let config = { packs: [] };
64	  try { config = JSON.parse(readFileSync(configPath, 'utf8')); } catch { /* no declaration — no active packs */ }
65	
66	  const { loadPacks, isActive } = await import(join(engineRoot, 'pack_loader', 'pack-registry.mjs'));
67	  const steps = (await loadPacks({ localRoot: projectRoot }))
68	    .filter((p) => isActive(p, config))
69	    .map((p) => ({ pack: p.id, step: join(p.dir, STEP_FILE) }))
70	    .filter((s) => existsSync(s.step));
71	  if (!steps.length) return; // nothing declared contributes a session-end step
72	
73	  for (const { pack, step } of steps) {
74	    hooklog('SessionEnd', `start ${pack}`);
75	    const run = spawnSync(process.execPath, [step], {
76	      cwd: projectRoot,
77	      encoding: 'utf8',
78	      timeout: STEP_TIMEOUT_MS,
79	      env: {
80	        ...process.env,
81	        // What the harness told US about this session, handed on so a step never has
82	        // to re-derive it. Named for the engine, not for any one step's CLI flags.
83	        ...(input.session_id ? { CLAUDINITE_SESSION_ID: String(input.session_id) } : {}),
84	        ...(input.transcript_path ? { CLAUDINITE_TRANSCRIPT: String(input.transcript_path) } : {}),
85	        // The issue this session was ABOUT, when its launcher knew one. A hook
86	        // firing never does — nothing tells a SessionEnd hook what the session was
87	        // for — so this is only ever set by an explicit invocation (the executor
88	        // naming its dispatch). Passed through verbatim: core states the fact, and
89	        // a step decides what, if anything, to do with it.
90	        ...(process.env.CLAUDINITE_SESSION_ISSUE ? { CLAUDINITE_SESSION_ISSUE: process.env.CLAUDINITE_SESSION_ISSUE } : {}),
91	      },
92	    });
93	    const tail = (run.stdout || run.stderr || '').trim().split('\n').pop() || '';
94	    hooklog('SessionEnd', run.status === 0
95	      ? `done exit=0 ${pack}${tail ? `: ${tail}` : ''}`
96	      : `done exit=0 ${pack} step failed (${run.signal ? `killed ${run.signal}` : `exit ${run.status}`})${tail ? `: ${tail}` : ''}`);
97	  }
98	}
99	
100	main().catch((e) => { hooklog('SessionEnd', `done exit=0 runner error: ${e.message}`); })
101	  .finally(() => process.exit(0)); // never block a session from ending
102

